/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */

#include <kunit/test.h>
#include <linux/module.h>
#include <linux/string.h>

static void agent_strncasecmp_basic_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("Kernel", "kERNEL", 7), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("MiXeD-Case_123", "mixed-case_123", 32), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("same", "same", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "xyz", 0), 0);
}

static void agent_strncasecmp_order_test(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("a", "B", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("B", "a", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abd", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abd", "abc", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "b", 1), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("b", "a", 1), 1);
}

static void agent_strncasecmp_length_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("abcX", "ABCY", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abcX", "ABCY", 4), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "ABdifferent", 2), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("ab", "ABdifferent", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("different", "DIFFERENT", 9), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("different", "DIFFERENT", 10), 0);
}

static void agent_strncasecmp_terminator_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("", "x", 1), -'x');
	KUNIT_EXPECT_EQ(test, strncasecmp("x", "", 1), 'x');
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "ABx", 8), -'x');
	KUNIT_EXPECT_EQ(test, strncasecmp("ABx", "ab", 8), 'x');
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "A", 2), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "A", 1), 0);
}

static void agent_strncasecmp_unsigned_byte_test(struct kunit *test)
{
	static const char high_lower[] = { (char)0x80, '\0' };
	static const char high_higher[] = { (char)0xff, '\0' };
	static const char ascii[] = { 'A', '\0' };
	static const char ascii_lower[] = { 'a', '\0' };

	KUNIT_EXPECT_LT(test, strncasecmp(high_lower, high_higher, 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp(high_higher, high_lower, 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(ascii, ascii_lower, 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(high_lower, high_lower, 2), 0);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_strncasecmp_basic_test),
	KUNIT_CASE(agent_strncasecmp_order_test),
	KUNIT_CASE(agent_strncasecmp_length_test),
	KUNIT_CASE(agent_strncasecmp_terminator_test),
	KUNIT_CASE(agent_strncasecmp_unsigned_byte_test),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suites(&agent_test_suite);

MODULE_LICENSE("GPL");
